"""Standalone interactive graph timeline from Nsight Systems CUPTI events."""
import json,sqlite3,pathlib,sys,collections
p=pathlib.Path(sys.argv[1]);db=sqlite3.connect(p);db.row_factory=sqlite3.Row
names=dict(db.execute('select id,value from StringIds'));rt={r['correlationId']:names[r['nameId']] for r in db.execute('select correlationId,nameId from CUPTI_ACTIVITY_KIND_RUNTIME')};groups=collections.defaultdict(list)
for r in db.execute('select * from CUPTI_ACTIVITY_KIND_KERNEL order by start'):
 if 'GraphLaunch' in rt.get(r['correlationId'],''):
  groups[r['correlationId']].append(dict(r))
graphs=[]
for ks in sorted(groups.values(),key=lambda ks:ks[0]['start'])[5:15]:
 start=min(k['start'] for k in ks)
 graphs.append([dict(t=(k['start']-start)/1e6,d=(k['end']-k['start'])/1e6,n=names[k['shortName']],s=k['streamId'],r=k['registersPerThread'],b=k['blockX']*k['blockY']*k['blockZ'],g=k['gridX']*k['gridY']*k['gridZ'],m=k['staticSharedMemory']+k['dynamicSharedMemory']) for k in ks])
html='''<!doctype html><meta charset="utf-8"><title>Bolt GPU 1 CUDA graph timeline</title><style>body{font:15px system-ui;margin:24px;background:#10151e;color:#e5edff}canvas{background:#192333;width:100%;height:300px}input{width:260px}pre{white-space:pre-wrap}label{margin-right:20px}</style><h1>Bolt: measured CUDA kernel timeline</h1><p>GPU 1 H200. CUPTI kernel intervals, grouped by stream. Hover for launch resources. These are kernel executions, not measured per-SM utilization. Resource occupancy is a theoretical upper bound; host driver denies hardware counters.</p><label>Graph <select id="graph"></select></label><label>Zoom <input id="zoom" type="range" min="1" max="40" value="1"></label><label>Position <input id="pos" type="range" min="0" max="1000" value="0"></label><canvas id="c"></canvas><pre id="detail">Hover over a kernel.</pre><p>Color: green MoE, blue dense GEMV, orange reduction, purple Marlin, grey other. Empty space means no displayed kernel on that stream; another stream may be executing.</p><script>const graphs=DATA;const c=document.querySelector('#c'),ctx=c.getContext('2d'),g=document.querySelector('#graph'),z=document.querySelector('#zoom'),p=document.querySelector('#pos');graphs.forEach((_,i)=>g.add(new Option(i,i)));let boxes=[];function draw(){const ks=graphs[+g.value],streams=[...new Set(ks.map(k=>k.s))],end=Math.max(...ks.map(k=>k.t+k.d)),width=end/+z.value,start=(end-width)*p.value/1000;c.width=c.clientWidth*devicePixelRatio;c.height=300*devicePixelRatio;ctx.setTransform(devicePixelRatio,0,0,devicePixelRatio,0,0);ctx.clearRect(0,0,c.clientWidth,300);boxes=[];ctx.fillStyle='#fff';ctx.fillText(start.toFixed(4)+' ms → '+(start+width).toFixed(4)+' ms',8,18);for(const k of ks){let x=80+(k.t-start)/width*(c.clientWidth-90),w=k.d/width*(c.clientWidth-90),y=50+streams.indexOf(k.s)*45;if(x+w<80||x>c.clientWidth)continue;ctx.fillStyle=k.n.includes('moe')?'#5dd39e':k.n.includes('reduce')?'#efa45b':k.n.toLowerCase().includes('marlin')?'#ba91ef':k.n.includes('gemv')?'#63a9ff':'#8b99ac';ctx.fillRect(Math.max(80,x),y,Math.min(w,c.clientWidth-x),25);boxes.push({x,w,y,k})}ctx.fillStyle='#fff';streams.forEach((s,i)=>ctx.fillText('stream '+s,2,68+i*45))}c.onmousemove=e=>{const r=c.getBoundingClientRect(),x=e.clientX-r.left,y=e.clientY-r.top,b=boxes.find(b=>x>=b.x&&x<=b.x+b.w&&y>=b.y&&y<=b.y+25);if(b)document.querySelector('#detail').textContent=JSON.stringify(b.k,null,2)+'\\n t=start ms, d=duration ms, r=registers/thread, b=threads/CTA, g=grid CTAs, m=shared bytes';};[g,z,p].forEach(v=>v.oninput=draw);window.onresize=draw;draw();</script>'''.replace('DATA',json.dumps(graphs))
p.with_suffix('.timeline.html').write_text(html)
print(p.with_suffix('.timeline.html'))
